"use client";
import { useState } from "react";
import axios from "axios";
import { useAuth } from "../../store/auth";
import { useRouter } from "next/navigation";

export default function Login() {
  const [cred, setCred] = useState({ email: "", password: "" });
  const { login } = useAuth();
  const router = useRouter();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/api/auth/jwt/create/",
        cred
      );
      const userRes = await axios.get(
        "http://127.0.0.1:8000/api/auth/users/me/",
        {
          headers: { Authorization: `Bearer ${res.data.access}` },
        }
      );
      login(res.data.access, userRes.data);
      router.push("/dashboard");
    } catch (err) {
      alert("Login failed");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[var(--wave-light)]">
      <form
        onSubmit={handleLogin}
        className="bg-white p-10 rounded-2xl shadow-2xl w-96"
      >
        <h2 className="text-3xl font-bold text-[var(--wave-blue)] mb-8 text-center">
          WaveTech
        </h2>
        <input
          type="email"
          placeholder="Email"
          className="w-full p-4 mb-4 border rounded-lg"
          onChange={(e) => setCred({ ...cred, email: e.target.value })}
          required
        />
        <input
          type="password"
          placeholder="Password"
          className="w-full p-4 mb-6 border rounded-lg"
          onChange={(e) => setCred({ ...cred, password: e.target.value })}
          required
        />
        <button className="w-full bg-[var(--wave-blue)] text-white py-4 rounded-lg text-lg hover:bg-blue-700">
          Login
        </button>
        <p className="text-center mt-4">
          No account?{" "}
          <a href="/register" className="text-[var(--wave-blue)] underline">
            Register here
          </a>
        </p>
      </form>
    </div>
  );
}
